<?php declare(strict_types=1); $heroActions = [['class' => 'button-white', 'href' => $demoUrl, 'label' => $t('actions.demo'), 'icon' => 'external-link', 'external' => true], ['class' => 'button-outline-light', 'href' => $route('contact'), 'label' => $t('actions.contact')]]; require dirname(__DIR__) . '/page-hero.php'; ?>
<section class="section"><div class="shell"><div class="metric-grid"><?php foreach ((array) $t('product.metrics', []) as $metric): ?><div><strong><?= $e($metric['value']) ?></strong><span><?= $e($metric['label']) ?></span></div><?php endforeach; ?></div><div class="section-head product-head"><div><span class="section-label"><?= $e($t('product.modules_label')) ?></span><h2><?= $e($t('product.modules_title')) ?></h2></div><p><?= $e($t('product.modules_copy')) ?></p></div><div class="module-list"><?php foreach ((array) $t('product.modules', []) as $index => $module): ?><article><div class="module-number"><?= str_pad((string) ($index + 1), 2, '0', STR_PAD_LEFT) ?></div><div><h3><?= $e($module['title']) ?></h3><p><?= $e($module['copy']) ?></p><ul><?php foreach ($module['points'] as $point): ?><li><?= $icon('check') ?><?= $e($point) ?></li><?php endforeach; ?></ul></div></article><?php endforeach; ?></div></div></section>
<section class="section architecture"><div class="shell architecture-grid"><div><span class="section-label light"><?= $e($t('product.architecture.label')) ?></span><h2><?= $e($t('product.architecture.title')) ?></h2><p><?= $e($t('product.architecture.copy')) ?></p></div><div class="architecture-stack"><?php foreach ((array) $t('product.architecture.layers', []) as $layer): ?><div><?= $icon($layer['icon']) ?><span><strong><?= $e($layer['title']) ?></strong><small><?= $e($layer['copy']) ?></small></span></div><?php endforeach; ?></div></div></section>
